int h1 = 0, h2 = n - 1, c1 = 0, c2 = n - 1, dem = 1;
while (h1 <= h2 && c1 <= c2) {
    for (int i = c1; i <= c2; i++) a[h1][i] = dem++;   // cạnh trên
    h1++;
    for (int i = h1; i <= h2; i++) a[i][c2] = dem++;   // cạnh phải
    c2--;
    for (int i = c2; i >= c1; i--) a[h2][i] = dem++;   // cạnh dưới
    h2--;
    for (int i = h2; i >= h1; i--) a[i][c1] = dem++;   // cạnh trái
    c1++;
}
// in: printf("%d ", a[i][j]);  n=5 -> 1 2 3 4 5 / 16 17 18 19 6 ...

int X[10000], idx = 0, i = 0;
while (idx < n * n) {
    if (nt(i)) X[idx++] = i;   // gom số nguyên tố vào X
    i++;
}
